// VOCAB-W2: more of the catalogue (docs/god/VOCAB.md) — vehicles (road, cycle, water, air, rail, construction), living
// things on the creature machinery (behaviours from the `behavior` component, gaits from motion.ts), water features and
// bodies (presets of river/1, lake/1, pier/1, scatter/2 where one fits), utilities, and the sound layer
// (`components.sound`, played by apps/web/src/gen-mesh/sound.ts). Origin on the floor at the footprint centre, front +z,
// metres, Eden palettes; budgets per category (vocab.triBudget).
import { box, cap, cbox, cone, cyl, extrude, lathe, limb, sph, tor, seat, stand, surface, hang, perch, bedSlot, withRole as dslWithRole } from './dsl.mjs';
import { presetDef, vocabDef } from './vocab-dsl.mjs';
import { quadruped, bird } from './creatures.mjs';

const C = { stone: '#b9b3a6', concrete: '#a9a49a', oak: '#9a6b43', walnut: '#5e3d27', pine: '#c79a63', iron: '#3b3d40', steel: '#8a8f94', brass: '#b8913f', cream: '#f2ead8',
  red: '#c23a2b', glass: '#3b4b55', flame: '#ffb347', white: '#f4f2ec', sage: '#3f6b5c', terracotta: '#c46a43', mustard: '#d9a63a', teal: '#2f6b6b', soot: '#2b2623', orange: '#f07c2a',
  navy: '#2f4a6b', water: '#4f8fa8', moss: '#5f7a45', tyre: '#2b2826', lamp: '#fff2c4', rear: '#d8402e' };
const PI = Math.PI;
const withRole = (role, pivot, shapes) => dslWithRole(role, pivot, shapes).map((s) => (s.__cbox ? { ...s, o: { ...s.o, role: s.role, pivot: s.pivot } } : s));
const when = (w, shapes) => !w ? shapes : shapes.map((s) => (s.__cbox ? { ...s, o: { ...s.o, when: w } } : { ...s, when: w }));
const wheel = (x, y, z, r, w = 0.24, c = 'tyre', seg = 10) => cyl([x, y, z], r, w, c, { roll: PI / 2, seg });
const wheels4 = (x, z1, z2, r, w) => [[-x, z1], [x, z1], [-x, z2], [x, z2]].map(([a, b]) => wheel(a, r, b, r, w));
const glassBox = (at, size, o = {}) => box(at, size, 'glass', o);   // opaque dark panes: the glass material reads as paint from outside
const sound = (kind, o = {}) => ({ kind, radius: o.radius ?? 14, volume: o.volume ?? 0.5, ...(o.when ? { when: o.when } : {}), mode: o.mode ?? 'loop' });
/** Every def with a sound may change its kind and loudness per instance. */
const soundParams = (kinds, def) => ({ sound: { type: 'enum', values: kinds, default: def, doc: 'what it sounds like (viewer, procedural)' }, loudness: { type: 'number', min: 0, max: 1, default: 0.5, doc: 'how loud, 0..1' } });

